using Microsoft.AspNetCore.HttpOverrides;
using System.Net.Http;

var builder = WebApplication.CreateBuilder(args);

// FIX 1 (ValidateScopes): Scoped IUserService was captured by singleton
//        CacheService. .NET 9 enables ValidateScopes in dev, which would
//        throw at startup. Changed CacheService to Scoped to match.
builder.Services.AddScoped<IUserService, UserService>();
builder.Services.AddScoped<ICacheService>(sp =>
    new CacheService(sp.GetRequiredService<IUserService>()));

// FIX 2 (SocketsHttpHandler): HttpClientFactory now uses SocketsHttpHandler
//        by default. The old cast to HttpClientHandler throws InvalidCastException.
//        Use ConfigurePrimaryHttpMessageHandler to set properties directly.
builder.Services.AddHttpClient("api")
    .ConfigurePrimaryHttpMessageHandler(() => new SocketsHttpHandler
    {
        UseCookies = false
    });

// FIX 3 (Header redaction): .NET 9 redacts all header values in Trace-level
//        HttpClientFactory logs by default. Allowlist the non-sensitive headers
//        you need for debugging.
builder.Services.ConfigureHttpClientDefaults(b =>
    b.RedactLoggedHeaders(h =>
        h != "X-Request-Id"
        && h != "X-Forwarded-For"
        && h != "X-Forwarded-Proto"));

// FIX 4 (ForwardedHeaders): .NET 9 ignores X-Forwarded-* headers from proxies
//        not in KnownProxies/KnownNetworks. Configure your trusted proxy.
builder.Services.Configure<ForwardedHeadersOptions>(options =>
{
    options.ForwardedHeaders = ForwardedHeaders.XForwardedFor;
    // Add your reverse proxy address(es) here:
    // options.KnownProxies.Add(System.Net.IPAddress.Parse("10.0.0.1"));
});

var app = builder.Build();
app.UseForwardedHeaders();
app.Run();

